'use client';
import Image from 'next/image';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { DbRows } from '@seapilot/contracts';
import { api, actorName, formatTime, type ConversationDetail, type OrderShipments } from '../src/lib/api';
import { Input, Textarea, Label, Card, Select, SelectTrigger, SelectValue, SelectContent, SelectItem, Accordion, AccordionItem, AccordionTrigger, AccordionContent, Alert, AlertDescription, Avatar, Badge, Brand, Button, Sheet, EmptyState, Package, Paperclip, ArrowUp, Plus, ShieldCheck, CheckCheck, Truck, X, MessageSquare } from '@seapilot/ui';

export function CustomerChat() {
  const [conversations, setConversations] = useState<DbRows['conversations'][]>([]);
  const [selected, setSelected] = useState('');
  const [thread, setThread] = useState<ConversationDetail | null>(null);
  const [order, setOrder] = useState<OrderShipments | null>(null);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [attachment, setAttachment] = useState<'parcel_a' | 'parcel_b_open' | ''>('');
  const [file, setFile] = useState<File | null>(null);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [evidence, setEvidence] = useState<DbRows['evidence'] | null>(null);
  const [busy, setBusy] = useState(false);
  const pending = useRef(false);
  const generation = useRef(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const draft = drafts[selected] ?? '';
  const refresh = useCallback(async () => {
    const version = ++generation.current;
    const [list, shipments] = await Promise.all([api.conversations('CUST001'), api.shipments('DH001')]);
    if (version !== generation.current) return;
    if (!list.ok) { setError(list.error); setLoading(false); return; }
    const sorted = list.data.sort((a, b) => a.opened_at.localeCompare(b.opened_at));
    setConversations(sorted);
    const id = sorted.some(item => item.id === selected) ? selected : sorted.at(-1)?.id ?? '';
    if (id !== selected) { setSelected(id); setThread(null); setAttachment(''); setFile(null); setDrafts({}); }
    if (shipments.ok) setOrder(shipments.data);
    if (id) {
      const result = await api.conversation(id);
      if (version !== generation.current) return;
      if (result.ok) setThread(result.data); else { setThread(null); setError(result.error); }
    } else setThread(null);
    setLoading(false);
  }, [selected]);
  useEffect(() => {
    let active = true;
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => { await refresh(); if (active) timer = setTimeout(poll, 2000); };
    void poll();
    return () => { active = false; clearTimeout(timer); generation.current += 1; };
  }, [refresh]);
  async function newConversation() {
    if (pending.current) return;
    pending.current = true; setBusy(true); setError(''); setNotice('');
    const result = await api.createConversation('CUST001');
    if (result.ok) { generation.current += 1; setConversations(previous => [...previous, result.data]); setSelected(result.data.id); setThread(null); setAttachment(''); setFile(null); setPickerOpen(false); setNotice('New conversation started. Earlier messages are still available.'); }
    else setError(result.error);
    pending.current = false; setBusy(false);
  }
  async function send() {
    if (pending.current || !selected || (!draft.trim() && !attachment && !file)) return;
    pending.current = true; setBusy(true); setError(''); setNotice('');
    try {
      // Clear only the successfully saved part, so a failed attachment can be retried without duplicating text.
      if (draft.trim()) {
        const result = await api.sendMessage(selected, draft);
        if (!result.ok) { setError(result.error); return; }
        setDrafts(previous => ({ ...previous, [selected]: '' }));
      }
      if (file || attachment) {
        const result = file ? await api.upload(selected, file) : await api.seedImage(selected, attachment as 'parcel_a' | 'parcel_b_open');
        if (!result.ok) { setError(`${result.error} Your text may already be saved. Retry the attachment or choose a sample.`); return; }
        setAttachment(''); setFile(null); setPickerOpen(false);
      }
      setNotice('Sent');
    } finally { await refresh(); pending.current = false; setBusy(false); }
  }
  return <>
    <header className="customer-header"><Brand /><div className="row"><span className="header-help">A little help, without starting over.</span><Badge tone="green">Connected demo</Badge><Avatar name="Lan Nguyen" /></div></header>
    <main id="main" className="customer-main">
      <div className="customer-intro"><div><h1>We’re here to help, Lan.</h1><p>One conversation closer to getting things sorted.</p></div><Button variant="outline" onClick={() => void newConversation()} disabled={busy || loading}><Plus />New conversation</Button></div>
      <div className="customer-grid">
        <Card className="customer-chat" role="region" aria-label="Support conversation">
          <div className="chat-header"><div className="row"><span className="brand-symbol"><MessageSquare size={18} /></span><div><h2>Your support team</h2><p className="muted small">We’ll keep the context, so you don’t have to.</p></div></div><Badge>{order?.order.id ?? 'Order'}</Badge></div>
          <div className="customer-messages" role="log" aria-label="Messages" aria-live="polite">
            <div className="day-divider">{thread ? `${formatTime(thread.conversation.opened_at)} · ${thread.conversation.id}` : loading ? 'Loading conversations…' : 'New conversation'}</div>
            {!thread?.messages.length && <EmptyState title="What can we help with?">{selected ? 'Tell us what happened with your order.' : 'Start a new conversation to contact support.'} Your earlier conversations stay on file.</EmptyState>}
            {thread?.messages.map(message => <article key={message.id} className={`message ${message.role === 'customer' ? 'own' : ''}`}><Avatar small name={message.role === 'customer' ? 'Lan Nguyen' : actorName(message.actor)} /><div className="message-body"><div className="message-meta"><strong>{message.role === 'customer' ? 'You' : `${actorName(message.actor)} · Support`}</strong><time>{formatTime(message.created_at)}</time><CheckCheck size={12} aria-label="Saved" /></div><div className="bubble">{message.text}</div></div></article>)}
            <div className="evidence-grid">{thread?.evidence.map(item => <Button variant="outline" key={item.id} onClick={() => setEvidence(item)}><Paperclip />{item.id} · {item.path.includes('/demo/') ? 'Sample image' : 'Image'}</Button>)}</div>
          </div>
          <form className="composer" onSubmit={event => { event.preventDefault(); void send(); }}>
            <div className="composer-box"><Label className="sr-only" htmlFor="customer-message">Your message</Label><Textarea id="customer-message" placeholder={selected ? 'Tell us what’s on your mind…' : 'Start a new conversation first'} maxLength={4000} value={draft} onChange={e => setDrafts(previous => ({ ...previous, [selected]: e.target.value }))} disabled={busy || !selected} />
              <div className="composer-tools"><Button variant="ghost" size="sm" aria-expanded={pickerOpen} onClick={() => setPickerOpen(!pickerOpen)} disabled={busy || !selected}><Paperclip />{file ? file.name : attachment ? '1 sample attached' : 'Attach image'}</Button><Button type="submit" disabled={busy || !selected || (!draft.trim() && !attachment && !file)}>{busy ? 'Sending…' : 'Send'}<ArrowUp /></Button></div>
              {pickerOpen && <div className="attachment-picker"><Label htmlFor="customer-file">Upload an image</Label><Input key={file?.name ?? 'empty'} id="customer-file" type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={event => { setFile(event.target.files?.[0] ?? null); setAttachment(''); }} /><Label htmlFor="customer-attachment" className="small">Or use a demo image</Label><Select value={attachment || 'none'} onValueChange={value => { setAttachment(value === 'none' ? '' : value as 'parcel_a' | 'parcel_b_open'); setFile(null); }} disabled={busy}><SelectTrigger id="customer-attachment"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Choose a sample</SelectItem><SelectItem value="parcel_a">Parcel A · shipping label</SelectItem><SelectItem value="parcel_b_open">Parcel B · opened parcel</SelectItem></SelectContent></Select>{(attachment || file) && <Button variant="ghost" size="icon" aria-label="Remove attachment" onClick={() => { setAttachment(''); setFile(null); }}><X /></Button>}<p className="muted small">JPEG, PNG or WebP, up to 10 MiB. Sample images are labeled illustrations.</p></div>}
            </div>
            <div className="composer-footnote"><ShieldCheck size={13} />Your messages stay with this conversation.</div>
            <p className="status-note" role="status">{notice}</p>{error && <Alert variant="destructive" className="error-note"><AlertDescription>{error}</AlertDescription></Alert>}
          </form>
        </Card>
        <aside className="customer-aside" aria-label="Order context"><Card className="order-aside"><div className="row between"><h2>Your order</h2><Package size={18} className="muted" /></div><p className="order-meta">{order?.order.id ?? 'Loading order…'} · {order?.parcels.length ?? 0} parcels</p>{order?.parcels.map(parcel => <div className="product-row" key={parcel.parcel_code}><div className="product-mark"><Package size={24} strokeWidth={1.3} /></div><div><p className="product-name">{parcel.items.map(item => item.name).join(', ')}</p><p className="product-detail">Parcel {parcel.parcel_code}</p><Badge tone={parcel.status === 'delivered' ? 'green' : 'amber'}>{parcel.status.replaceAll('_', ' ')}</Badge></div></div>)}<p className="order-note"><Truck size={15} style={{ display: 'inline', marginRight: 6 }} />Your items travel separately. We can help if something is missing from a delivered parcel.</p></Card>
          <div className="support-note"><h3>A fresh chat. The same context.</h3><p>You don’t need to send your story or attachments again. Your support team can pick up where you left off.</p></div>
          <Accordion type="single" collapsible className="customer-history"><AccordionItem value="history"><AccordionTrigger>Earlier conversations ({conversations.length})</AccordionTrigger><AccordionContent>{conversations.map(c => <Button key={c.id} size="sm" disabled={busy} variant={selected === c.id ? 'secondary' : 'outline'} onClick={() => { generation.current += 1; setSelected(c.id); setThread(null); setAttachment(''); setFile(null); }}>{c.id} · {formatTime(c.opened_at)}</Button>)}</AccordionContent></AccordionItem></Accordion>
        </aside>
      </div><div className="local-notice">Connected to your support team. Messages refresh every 2 seconds.</div>
    </main>
    <Sheet open={!!evidence} onOpenChange={open => !open && setEvidence(null)} title="Conversation attachment" description="Customer-supplied evidence. Seed images are illustrative.">{evidence && <div className="case-section"><Image unoptimized width={640} height={480} src={api.fileUrl(evidence.path)} alt={`Customer attachment ${evidence.id}`} style={{ width: '100%', height: 'auto' }} /><Badge tone="blue">{evidence.source}</Badge><p>{formatTime(evidence.created_at)}</p></div>}</Sheet>
  </>;
}
'use client';
import Image from 'next/image';
import { useCallback, useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import type { AgentSuggestion } from '@seapilot/contracts';
import { api, CS_IDENTITIES, actorName, formatTime, type ApiResult, type ConversationDetail, type CaseDetail, type CaseContext, type OrderShipments } from '../src/lib/api';
import { Input, Textarea, Label, Tabs, TabsList, TabsTrigger, TabsContent, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Alert, AlertDescription, Avatar, Badge, Brand, Button, Sheet, EmptyState, SourceBadge, ArrowLeft, ArrowRight, CheckCheck, Clock3, Inbox, LifeBuoy, Link2, PanelRight, Search, Send, ShieldCheck, Paperclip } from '@seapilot/ui';
import { CasePanel } from './case-panel';
import { DemoControls } from './demo-controls';
import { refreshDraftAfter } from '../src/lib/review-flow';
import { selectIdentity, useIdentity } from '../src/lib/identity';

type Snapshot = { threads: ConversationDetail[]; selected: string; detail: CaseDetail | null; context: CaseContext | null; order: OrderShipments | null };
const empty: Snapshot = { threads: [], selected: '', detail: null, context: null, order: null };
// Read-only refreshes and ai_suggestion audit events must not invalidate a draft.
function fingerprint(thread: ConversationDetail | undefined, order: OrderShipments | null) {
  return JSON.stringify([thread?.conversation, thread?.messages, thread?.evidence, order?.parcels.map(parcel => [parcel.parcel_code, parcel.status])]);
}
const customerName = (id: string) => ({ CUST001: 'Lan Nguyen', CUST002: 'Minh Tran', CUST003: 'Sam Lee' })[id] ?? id;
export function Workspace({ demoEnabled }: { demoEnabled: boolean }) {
  const [snapshot, setSnapshot] = useState<Snapshot>(empty);
  const [selected, setSelected] = useState('');
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('all');
  const [showThread, setShowThread] = useState(true);
  const [details, setDetails] = useState(false);
  const [evidence, setEvidence] = useState<ConversationDetail['evidence'][number] | null>(null);
  const [help, setHelp] = useState(false);
  const identity = useIdentity();
  const [draft, setDraft] = useState('');
  const [title, setTitle] = useState('');
  const [suggestion, setSuggestion] = useState<{ data: AgentSuggestion; fingerprint: string } | null>(null);
  const [dismissedMatch, setDismissedMatch] = useState(false);
  const [working, setBusy] = useState(false);
  const [demoBusy, setDemoBusy] = useState(false);
  const busy = working || demoBusy;
  const [loading, setLoading] = useState(true);
  const [blocked, setBlocked] = useState(false);
  const [error, setError] = useState('');
  const [readError, setReadError] = useState('');
  const [notice, setNotice] = useState('');
  const pending = useRef(false);
  const generation = useRef(0);
  const thread = snapshot.selected === selected ? snapshot.threads.find(item => item.conversation.id === selected) : undefined;
  const currentFingerprint = fingerprint(thread, snapshot.order);
  const stale = !!suggestion && suggestion.fingerprint !== currentFingerprint;
  const canApprove = !!suggestion && !stale && !blocked && !readError && !!thread;
  const task = snapshot.detail?.tasks.find(item => item.team === 'operations');
  const actionPending = !!suggestion?.data.proposed_action && !task;
  const match = suggestion?.data.suggested_case_id;
  const linked = !!thread?.conversation.case_id;
  const customer = customerName(thread?.conversation.customer_id ?? 'CUST001');
  const clearReview = useCallback(() => { setSuggestion(null); setDraft(''); setTitle(''); setDismissedMatch(false); setBlocked(false); setError(''); setNotice(''); }, []);
  const refresh = useCallback(async () => {
    const version = ++generation.current;
    const list = await api.conversations();
    if (version !== generation.current) return;
    if (!list.ok) { setReadError(list.error); setLoading(false); return; }
    const rows = list.data.sort((a, b) => b.opened_at.localeCompare(a.opened_at));
    const results = await Promise.all(rows.map(row => api.conversation(row.id)));
    if (version !== generation.current) return;
    const failed = results.find(result => !result.ok);
    if (failed && !failed.ok) { setReadError(failed.error); setLoading(false); return; }
    const threads = results.flatMap(result => result.ok ? [result.data] : []);
    const id = rows.some(row => row.id === selected) ? selected : rows[0]?.id ?? '';
    const active = threads.find(item => item.conversation.id === id);
    const caseId = active?.conversation.case_id;
    let detail: CaseDetail | null = null;
    let context: CaseContext | null = null;
    let order: OrderShipments | null = null;
    if (caseId) {
      const [caseResult, contextResult] = await Promise.all([api.caseDetail(caseId), api.caseContext(caseId)]);
      if (version !== generation.current) return;
      if (!caseResult.ok || !contextResult.ok) { setReadError(!caseResult.ok ? caseResult.error : !contextResult.ok ? contextResult.error : 'Could not load case'); setLoading(false); return; }
      detail = caseResult.data; context = contextResult.data;
    }
    const orderId = detail?.case.order_id ?? (active?.conversation.customer_id === 'CUST001' ? 'DH001' : null);
    if (orderId) {
      const result = await api.shipments(orderId);
      if (version !== generation.current) return;
      if (!result.ok) { setReadError(result.error); setLoading(false); return; }
      order = result.data;
    }
    if (id !== selected) { setSelected(id); clearReview(); }
    const next = { threads, selected: id, detail, context, order };
    setSnapshot(next); setReadError(''); setLoading(false);
    return next;
  }, [selected, clearReview]);
  useEffect(() => {
    let active = true;
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => { if (!pending.current) await refresh(); if (active) timer = setTimeout(poll, 2000); };
    void poll();
    return () => { active = false; clearTimeout(timer); generation.current += 1; };
  }, [refresh]);
  async function run<T>(work: () => Promise<ApiResult<T>>, success: string, onSuccess?: (data: T) => void) {
    if (pending.current || demoBusy) return;
    pending.current = true; generation.current += 1; setBusy(true); setError(''); setNotice('');
    try {
      const result = await work();
      if (!result.ok) { setBlocked(true); setError(result.error); return; }
      onSuccess?.(result.data); setNotice(success);
      await refresh();
    } finally { pending.current = false; setBusy(false); }
  }
  function suggest() {
    if (!thread) return;
    const key = currentFingerprint;
    setSuggestion(null); setDraft('');
    void run(() => api.suggest(selected), 'Suggestion ready for review.', data => { setSuggestion({ data, fingerprint: key }); setBlocked(false); });
  }
  function approveReply() {
    if (!canApprove || actionPending || !draft.trim() || (!linked && (!title.trim() || (!!match && !dismissedMatch)))) return;
    void run(() => api.approveReply(selected, draft, CS_IDENTITIES[identity], linked ? undefined : title), 'Sent', () => { setDraft(''); setSuggestion(null); });
  }
  function updateAfter(mutate: () => Promise<ApiResult<unknown>>, updating: string, success: string) {
    const conversationId = selected;
    void run(() => refreshDraftAfter({
      mutate, conversationId, suggest: api.suggest,
      onUpdating: () => { setSuggestion(null); setDraft(''); setBlocked(true); setNotice(updating); },
      loadFingerprint: async () => {
        const next = await refresh();
        const active = next?.threads.find(item => item.conversation.id === conversationId);
        return next?.selected === conversationId && active ? fingerprint(active, next.order) : undefined;
      },
    }), success, review => { setSuggestion(review); setDraft(review.data.draft_reply); setBlocked(false); });
  }
  function linkCase(caseId: string) {
    updateAfter(() => api.link(caseId, selected, CS_IDENTITIES[identity]), 'Updating draft...', 'Conversation linked. Updated draft ready for review.');
  }
  function escalate() {
    const action = suggestion?.data.proposed_action;
    if (!canApprove || !linked || !action || task) return;
    updateAfter(() => api.approveAction(selected, action, CS_IDENTITIES[identity]), 'Updating draft after escalation...', 'Escalated. Updated draft ready for review.');
  }
  const conversations = snapshot.threads.filter(item => (filter !== 'needs' || item.messages.at(-1)?.role
